<style>
    .citeck-widget-contacts .form-group {
        margin: 0;
    }

    /* The platform sets a border and 0.65rem/0.5rem padding on every datagrid cell. Here each
       cell holds a whole contact card, so the cell must not add any frame of its own. The
       selector has to stay inside .citeck-widget-contacts and outrank
       `.formio-component-datagrid table.table-bordered td`, otherwise it either leaks onto
       every table of the page or loses and does nothing. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered th,
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered td {
        padding: 0 0 16px;
        border: none;
        height: auto;
    }

    /* The gap belongs between the cards, not after the last one - otherwise a widget of
       collapsed cards ends with an empty strip as tall as a card. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered tr:last-child > td {
        padding-bottom: 0;
    }

    /* The step below the title belongs to the body, not to the title: a collapsed body is
       display:none, so its margin disappears with it and collapsed cards do not reserve room
       for content they are not showing. */
    .citeck-widget-contacts .card > .card-header {
        padding-bottom: 0;
    }

    /* Direct child, not descendant: a contact card sits inside a wrapper panel, so a descendant
       selector applied this inset twice and squeezed the content into the middle of the widget.
       The card adds no inset of its own - the same as on the counterparty form, where the
       fields simply sit in the padded content area around the grid. */
    .citeck-widget-contacts .card > .card-body.panel-body {
        padding: 0 !important;
        margin-top: 11px;
        margin-bottom: 0;
        /* the rows carry their own 5px above and below; the platform puts a 1rem flex gap on a
           datagrid panel body, which pushed the comment 16px away while the fields sat 10px
           apart - !important because that rule outranks this one */
        gap: 0 !important;
    }

    /* Only the read-only rows. While a field is being edited inline, the very same dl becomes
       the editor and carries `formio-component`; squeezing its sides to zero and dropping its
       bottom border left the label against the frame and the frame unfinished. */
    .citeck-widget-contacts-comment_view-mode,
    .citeck-widget-contacts-columns dl:not(.formio-component) {
        border-bottom: none !important;
        padding: 5px 0 !important;
    }

    .citeck-widget-contacts-comment_view-mode dd,
    .citeck-widget-contacts-columns dd {
        color: #444444;
        font-weight: 600;
    }

    .citeck-widget-contacts-comment_view-mode dt,
    .citeck-widget-contacts-columns dt {
        color: #B7B7B7;
    }
    .citeck-widget-contacts-comment_view-mode dt:after,
    .citeck-widget-contacts-columns dt:after {
        content: ":";
    }

    /* Keep the platform's title chip (`.formio-form .card .card-title`) - with several contacts
       in one widget it is the only thing separating one card from the next. Only the vertical
       rhythm and the icon alignment are adjusted here. */
    .citeck-widget-contacts .card .card-title {
        margin-top: 2px;
        margin-bottom: 0 !important;
        margin-left: 0;
        font-size: 14px !important;

        display: flex;
        gap: 3px;
        align-items: center;
    }

    /* The platform sizes the row-removal button to the height of a form input (40px) so that it
       lines up with the fields of a normal data grid. Here it stands next to the 30px title
       chip, so it has to match the chip instead. The platform selector is repeated with the
       widget class in front of it, otherwise its four classes and three elements win. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered
    td.formio-remove-column button.formio-button-remove-row {
        width: 32px;
        height: 30px;
        padding: 0;
        margin-top: 2px;
    }

    /* 8px of inset, the 32px button and 8px more on the other side: at 40px the button ended
       up flush against the right edge of the grid frame. */
    .citeck-widget-contacts .formio-remove-column {
        width: 48px;
        padding-left: 8px !important;
        padding-right: 8px !important;
    }

    /* --- the dialog ---------------------------------------------------------------------- */

    /* The contacts editor on the counterparty form is the reference: the grid sits straight in
       the padded content area of the dialog, with no frame of its own. Our widget is a panel,
       and its frame turned the dialog into a box inside a box. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts,
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts > .card-body.panel-body {
        border: none !important;
        background: transparent !important;
    }

    /* The frame around the contacts in the dialog is drawn by the data grid itself, as a 1px
       spread box-shadow on the table. Zeroing the cell padding - which the read-only layout
       needs - left the heading, the fields and the removal button pressed against that frame,
       and moving the whole table only changed the distance to the dialog, not to the frame.
       The reference form keeps the cell padding, so its contents sit 8px inside the frame. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts > .card-body.panel-body {
        padding-left: 20px !important;
        padding-right: 20px !important;
    }

    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts .formio-component-datagrid
    table.table-bordered td {
        padding: 10px 8px 16px;
    }

    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts .formio-component-datagrid
    table.table-bordered tr:last-child > td {
        padding-bottom: 10px;
    }

    /* `.form-group { margin: 0 }` above is right for the read-only rows, but in the dialog it
       leaves 3px between a field and the label of the next one. 16px is what the counterparty
       form uses. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts .form-group {
        margin-bottom: 16px;
    }

    /* The checkbox is the only control here without a label above it, so it started where the
       labels of the neighbouring fields start and floated half a row above them. The offset is
       the height of a label plus the gap under it, which puts the box on the same line as the
       field beside it. The box itself is drawn by the span, not by the input - the input has no
       size - so nothing here may shift the label horizontally. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts .formio-component-contactMain {
        /* padding, not margin: a top margin here collapses with the bottom margin of the field
           above and only a few of the pixels survive. 22px is the label block the checkbox does
           not have, 11px centres its 18px box against the 40px field beside it. */
        padding-top: 33px;
    }
</style>

